// Lëvizja me Foreach
string[] cars = {"Volvo", "BMW", "Ford"};
foreach (string i in cars) {
  Console.WriteLine(i);
}

// Cikli While me Break
int i = 0;
while (i < 10) {
  Console.WriteLine(i);
  i++;
  if (i == 4) break; // Përfundon para kohe
}

